from lib import *
CODE, BASE = 'pc', 122
RM = lambda v: f'RM{v}'
C = lambda v: f'{v:,}'

def build():
    L = []
    def add(i, *a): L.append(level(CODE, i, BASE + i, *a))
    add(1, 'number-sense', 'number-line', 'adventurer', 'bridge',
        T('Treasure Trail', 'Jejak Harta Karun'),
        T('The pirate map has marks on a long trail. Slide the ship to the right mark!', 'Peta lanun mempunyai tanda pada jejak yang panjang. Gelongsorkan kapal ke tanda yang betul!'),
        T('Place numbers on lines up to 10,000.', 'Meletakkan nombor pada garis sehingga 10,000.'),
        'Jolly', T('Jolly follows every trail to the end.', 'Jolly mengikuti setiap jejak sehingga ke penghujung.'),
        [numberline(450, 0, 1000, 50, 250), numberline(700, 0, 1000, 100, 200), numberline(8500, 0, 10000, 500, 2500),])
    add(2, 'operations', 'addition', 'adventurer', 'chest',
        T('Counting Coins', 'Mengira Syiling'),
        T('The pirates counted their gold. Add and subtract the big numbers one step at a time!', 'Para lanun mengira emas mereka. Tambah dan tolak nombor besar satu langkah pada satu masa!'),
        T('Add and subtract numbers up to 10,000.', 'Menambah dan menolak nombor sehingga 10,000.'),
        'Goldie', T('Goldie always keeps one coin in her hat.', 'Goldie sentiasa menyimpan sekeping syiling dalam topinya.'),
        [steps([step(T('The pirates find 245 coins on Monday and 318 on Tuesday. How many coins is that?', 'Para lanun menjumpai 245 syiling pada hari Isnin dan 318 pada hari Selasa. Berapa syiling itu?'), 563, '245+318'),
                step(T('On Wednesday they find 127 more. How many coins now?', 'Pada hari Rabu mereka menjumpai 127 lagi. Berapa syiling sekarang?'), 690, '563+127'),
                step(T('They give 250 coins to the captain. How many coins are left?', 'Mereka memberikan 250 syiling kepada kapten. Berapa syiling yang tinggal?'), 440, '690-250')],
               T('Add first, then subtract.', 'Tambah dahulu, kemudian tolak.'), T('245 + 318 = 563, then 563 + 127 = 690, then 690 − 250 = 440.', '245 + 318 = 563, kemudian 563 + 127 = 690, kemudian 690 − 250 = 440.'), 'pc2a'),
         steps([step(T('A chest has 1,250 gold coins. The crew adds 875. How many coins is that?', 'Sebuah peti mempunyai 1,250 syiling emas. Kru menambah 875. Berapa syiling itu?'), 2125, '1250+875', C),
                step(T('They spend 1,400 coins on a ship. How many coins are left?', 'Mereka membelanjakan 1,400 syiling untuk sebuah kapal. Berapa syiling yang tinggal?'), 725, '2125-1400', C),
                step(T('Then they find 380 more. How many coins now?', 'Kemudian mereka menjumpai 380 lagi. Berapa syiling sekarang?'), 1105, '725+380', C)],
               T('Take it one step at a time.', 'Selesaikan satu langkah pada satu masa.'), T('1,250 + 875 = 2,125, then 2,125 − 1,400 = 725, then 725 + 380 = 1,105.', '1,250 + 875 = 2,125, kemudian 2,125 − 1,400 = 725, kemudian 725 + 380 = 1,105.'), 'pc2b'),
         steps([step(T('A treasure has 4,360 pearls and 2,845 diamonds. How many jewels is that?', 'Sebuah harta karun mempunyai 4,360 mutiara dan 2,845 berlian. Berapa permata itu?'), 7205, '4360+2845', C),
                step(T('The captain sells 3,960 jewels. How many jewels are left?', 'Kapten menjual 3,960 permata. Berapa permata yang tinggal?'), 3245, '7205-3960', C),
                step(T('Then 1,755 more jewels are found. How many jewels now?', 'Kemudian 1,755 permata lagi dijumpai. Berapa permata sekarang?'), 5000, '3245+1755', C)],
               T('Line up the digits by place value.', 'Selaraskan digit mengikut nilai tempat.'), T('4,360 + 2,845 = 7,205, then 7,205 − 3,960 = 3,245, then 3,245 + 1,755 = 5,000.', '4,360 + 2,845 = 7,205, kemudian 7,205 − 3,960 = 3,245, kemudian 3,245 + 1,755 = 5,000.'), 'pc2c')])
    add(3, 'operations', 'money', 'adventurer', 'chest',
        T('Pay the Pirates', 'Bayar Para Lanun'),
        T('Every pirate wants to be paid in exact coins. Pay each one correctly!', 'Setiap lanun mahu dibayar dengan syiling yang tepat. Bayar setiap seorang dengan betul!'),
        T('Make exact amounts of money.', 'Membentuk jumlah wang yang tepat.'),
        'Penny Pip', T('Penny Pip counts every sen twice.', 'Penny Pip mengira setiap sen dua kali.'),
        [coins(130, [5, 10, 20, 50]), coins(265, [5, 10, 20, 50, 100]), coins(480, [10, 20, 50, 100], 8)])
    add(4, 'number-sense', 'place-value', 'adventurer', 'door',
        T('Chest Codes', 'Kod Peti'),
        T('Each treasure chest has a number lock. Build the number with place value!', 'Setiap peti harta karun mempunyai kunci nombor. Bina nombor itu dengan nilai tempat!'),
        T('Build numbers up to 9,999 with place value.', 'Membina nombor sehingga 9,999 dengan nilai tempat.'),
        'Locky', T('Locky guards the keys on a chain.', 'Locky menjaga kunci pada rantai.'),
        [placevalue(630, [100, 10, 1]), placevalue(3407, [1000, 100, 10, 1]), placevalue(6050, [1000, 100, 10, 1])])
    add(5, 'operations', 'addition', 'master', 'scale',
        T('Weigh the Loot', 'Timbang Rampasan'),
        T('The loot goes on the scale in grams. Choose the bags that add up to the total!', 'Rampasan diletakkan di atas penimbang dalam gram. Pilih beg yang jumlahnya sama dengan jumlah keseluruhan!'),
        T('Add masses in grams.', 'Menambah jisim dalam gram.'),
        'Weighty Jack', T('Weighty Jack lifts a bag in each hand.', 'Weighty Jack mengangkat satu beg di setiap tangan.'),
        [balance(500, [120, 250, 180, 330, 70, 150]), balance(1000, [350, 450, 250, 300, 700, 150]), balance(1200, [300, 450, 600, 250, 350, 500], 3)])
    add(6, 'number-sense', 'place-value', 'master', 'door',
        T('Digit Doubloons', 'Doubloon Digit'),
        T('Arrange the digit doubloons to make the number the captain asks for!', 'Susun doubloon digit untuk membentuk nombor yang diminta oleh kapten!'),
        T('Order digits to make the largest and smallest numbers.', 'Menyusun digit untuk membentuk nombor terbesar dan terkecil.'),
        'Doubloon', T('Doubloon shines brighter in the right place.', 'Doubloon bersinar lebih terang di tempat yang betul.'),
        [digitarrange([3, 8, 1, 6], 'largest'), digitarrange([4, 0, 7, 9, 2], 'smallest'), digitarrange([6, 0, 3, 5, 9], 'largest')])
    add(7, 'number-sense', 'patterns', 'adventurer', 'lanterns',
        T('Cannon Counts', 'Kiraan Meriam'),
        T('The cannons fire in a pattern. How many shots come next?', 'Meriam menembak dalam satu pola. Berapa tembakan yang datang seterusnya?'),
        T('Continue patterns that count down, count on and double.', 'Menyambung pola yang mengira ke bawah, ke atas dan berganda.'),
        'Boomer', T('Boomer is not as loud as he looks.', 'Boomer tidak sebising rupanya.'),
        [pattern('arith', 1000, -150, 6, seed='pc7a'), pattern('geo', 5, 2, 5, seed='pc7b'), pattern('arith', 250, 250, 5, hidden=2, seed='pc7c')])
    add(8, 'shape-data', 'data', 'master', 'lighthouse',
        T('Loot Chart', 'Carta Rampasan'),
        T('The first mate drew a chart of the loot. Read it carefully!', 'Pegawai pertama melukis carta rampasan. Bacalah dengan teliti!'),
        T('Read bar charts: differences, totals and averages.', 'Membaca carta palang: beza, jumlah dan purata.'),
        'Mateo', T('Mateo writes down every coin in his logbook.', 'Mateo mencatat setiap syiling dalam buku lognya.'),
        [chart([(T('Gold', 'Emas'), 60, 'sun'), (T('Silver', 'Perak'), 35, 'sky'), (T('Pearls', 'Mutiara'), 45, 'grape')], ('diff', 0, 1), T('pieces', 'keping')),
         chart([(T('Gold', 'Emas'), 40, 'sun'), (T('Silver', 'Perak'), 55, 'sky'), (T('Pearls', 'Mutiara'), 25, 'grape'), (T('Rubies', 'Delima'), 30, 'coral')], ('sum', [0, 1, 2, 3]), T('pieces', 'keping')),
         chart([(T('Gold', 'Emas'), 20, 'sun'), (T('Silver', 'Perak'), 45, 'sky'), (T('Pearls', 'Mutiara'), 30, 'grape'), (T('Rubies', 'Delima'), 35, 'coral'), (T('Emeralds', 'Zamrud'), 20, 'mint')], ('mean',), T('pieces', 'keping'))])
    add(9, 'reasoning', 'money', 'master', 'ferry',
        T('Pirate Shopping', 'Membeli-belah Lanun'),
        T('The crew goes shopping on Parrot Island. Work out the cost of everything!', 'Kru pergi membeli-belah di Pulau Burung Kakak Tua. Kira harga setiap barang!'),
        T('Costs, change and sharing money.', 'Harga, baki dan perkongsian wang.'),
        'Polly', T('Polly repeats every price she hears.', 'Polly mengulang setiap harga yang didengarnya.'),
        [steps([step(T('The captain has RM240 to share equally between 6 pirates. How much does each pirate get?', 'Kapten mempunyai RM240 untuk dikongsi sama banyak antara 6 lanun. Berapa yang diperoleh setiap lanun?'), 40, '240/6', RM),
                step(T('Each pirate buys a hat for RM15. How much money does each pirate have left?', 'Setiap lanun membeli sebuah topi dengan harga RM15. Berapa wang yang tinggal pada setiap lanun?'), 25, '40-15', RM),
                step(T('How much money is left for all 6 pirates?', 'Berapa wang yang tinggal untuk kesemua 6 lanun?'), 150, '25*6', RM)],
               T('Share first, then take away the hat.', 'Kongsi dahulu, kemudian tolak harga topi.'), T('240 ÷ 6 = 40, then 40 − 15 = 25, then 25 × 6 = 150.', '240 ÷ 6 = 40, kemudian 40 − 15 = 25, kemudian 25 × 6 = 150.'), 'pc9a'),
         steps([step(T('A parrot costs RM85. How much do 3 parrots cost?', 'Seekor burung kakak tua berharga RM85. Berapa harga 3 ekor?'), 255, '3*85', RM),
                step(T('You pay with RM300. How much change do you get?', 'Anda membayar dengan RM300. Berapa baki yang anda terima?'), 45, '300-255', RM),
                step(T('You spend RM36 of the change on treats. How much change is left?', 'Anda membelanjakan RM36 daripada baki untuk makanan. Berapa baki yang tinggal?'), 9, '45-36', RM)],
               T('Multiply, then find the change.', 'Darab, kemudian cari baki.'), T('3 × 85 = 255, then 300 − 255 = 45, then 45 − 36 = 9.', '3 × 85 = 255, kemudian 300 − 255 = 45, kemudian 45 − 36 = 9.'), 'pc9b'),
         steps([step(T('A treasure map costs RM125. How much do 4 maps cost?', 'Sekeping peta harta karun berharga RM125. Berapa harga 4 keping?'), 500, '4*125', RM),
                step(T('The crew has RM800. How much money is left?', 'Kru mempunyai RM800. Berapa wang yang tinggal?'), 300, '800-500', RM),
                step(T('The rest is shared equally between 5 pirates. How much does each pirate get?', 'Bakinya dikongsi sama banyak antara 5 lanun. Berapa yang diperoleh setiap lanun?'), 60, '300/5', RM)],
               T('Work out the maps first.', 'Kira harga peta dahulu.'), T('4 × 125 = 500, then 800 − 500 = 300, then 300 ÷ 5 = 60.', '4 × 125 = 500, kemudian 800 − 500 = 300, kemudian 300 ÷ 5 = 60.'), 'pc9c')])
    add(10, 'reasoning', 'multi-step', 'master', 'windmill',
        T('Pirate Finale', 'Kemuncak Lanun'),
        T('The legendary treasure is almost yours! Solve three steps to open the final chest.', 'Harta karun legenda hampir menjadi milik anda! Selesaikan tiga langkah untuk membuka peti terakhir.'),
        T('Multi-step problems with big numbers, money and distance.', 'Masalah berbilang langkah dengan nombor besar, wang dan jarak.'),
        'Captain Pip', T('Captain Pip never loses his way.', 'Captain Pip tidak pernah sesat.'),
        [steps([step(T('A chest holds 8 bags with 125 coins in each bag. How many coins?', 'Sebuah peti mengandungi 8 beg dengan 125 syiling dalam setiap beg. Berapa syiling?'), 1000, '8*125', C),
                step(T('The pirates take 3 bags. How many coins is that?', 'Para lanun mengambil 3 beg. Berapa syiling itu?'), 375, '3*125'),
                step(T('How many coins are left in the chest?', 'Berapa syiling yang tinggal dalam peti?'), 625, '1000-375')],
               T('Find the coins in one bag first.', 'Cari syiling dalam satu beg dahulu.'), T('8 × 125 = 1,000, then 3 × 125 = 375, then 1,000 − 375 = 625.', '8 × 125 = 1,000, kemudian 3 × 125 = 375, kemudian 1,000 − 375 = 625.'), 'pc10a'),
         steps([step(T('A ship sails 45 km each day for 6 days. How many km is that?', 'Sebuah kapal belayar 45 km setiap hari selama 6 hari. Berapa km itu?'), 270, '6*45', lambda v: f'{v} km'),
                step(T('The island is 400 km away. How many km are still to go?', 'Pulau itu 400 km jauhnya. Berapa km lagi yang perlu dilalui?'), 130, '400-270', lambda v: f'{v} km'),
                step(T('The ship sails the rest in 2 equal days. How many km each day?', 'Kapal itu belayar baki itu dalam 2 hari yang sama. Berapa km setiap hari?'), 65, '130/2', lambda v: f'{v} km')],
               T('Multiply, then subtract, then share.', 'Darab, kemudian tolak, kemudian kongsi.'), T('6 × 45 = 270, then 400 − 270 = 130, then 130 ÷ 2 = 65.', '6 × 45 = 270, kemudian 400 − 270 = 130, kemudian 130 ÷ 2 = 65.'), 'pc10b'),
         steps([step(T('A pirate finds 3 chests with 250 coins in each. How many coins?', 'Seorang lanun menjumpai 3 peti dengan 250 syiling dalam setiap satu. Berapa syiling?'), 750, '3*250'),
                step(T('He also finds a bag of 125 coins. How many coins in total?', 'Dia juga menjumpai sebeg 125 syiling. Berapa syiling kesemuanya?'), 875, '750+125'),
                step(T('The coins are shared equally between 5 pirates. How many coins does each get?', 'Syiling itu dikongsi sama banyak antara 5 lanun. Berapa syiling yang diperoleh setiap orang?'), 175, '875/5')],
               T('Multiply, then add, then share.', 'Darab, kemudian tambah, kemudian kongsi.'), T('3 × 250 = 750, then 750 + 125 = 875, then 875 ÷ 5 = 175.', '3 × 250 = 750, kemudian 750 + 125 = 875, kemudian 875 ÷ 5 = 175.'), 'pc10c')])
    return L
